          "bg": [
                    "CNBG"
          ],
          "region_code": [
                    "026902"
          ],
          "office_code": [
                    "026921"
          ],
          "country_code": "EG",
          "network_id": [],
          "customer_number": [],
          "product_line_map": [],
          "product_category": [],
          "t1_operator": [],
          "branch_code": [],
          "subnet_code": [],
          "group_by": "t1_operator",
          "type": "planb",
          "need_summary": true
};
